-- STAGING ONLY 488: canonical receipt read-back must compare truthful NULL-hour provenance, not require job_card for every row.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-488-null-hours-readback',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827037000' AND name='487_unknown_hours_receipt_contract') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827037000') OR encode(extensions.digest(convert_to(pg_get_functiondef('public.read_pdc_jobcard_attachment_import_receipt(uuid)'::regprocedure),'UTF8'),'sha256'),'hex')<>'317ad42b4bb63209188777081dad89583123752ec373359a7bdcad3c38f5f5e6' THEN RAISE EXCEPTION 'PDC_488_TARGET_HEAD_OR_FUNCTION_MISMATCH' USING errcode='55000';END IF;END $g$;DO $patch$ DECLARE s text;old text:=$old$or ol.description<>sr.description or ol.estimated_hours<>sr.estimated_hours
        or ol.estimated_hours_source<>'job_card'$old$;new text:=$new$or ol.description is distinct from sr.description or ol.estimated_hours is distinct from sr.estimated_hours
        or ol.estimated_hours_source is distinct from sr.estimated_hours_source$new$;BEGIN s:=pg_get_functiondef('public.read_pdc_jobcard_attachment_import_receipt(uuid)'::regprocedure);IF length(s)-length(replace(s,old,''))<>length(old) THEN RAISE EXCEPTION 'PDC_488_REPLACEMENT_CARDINALITY';END IF;s:=replace(s,old,new);EXECUTE s;END $patch$;REVOKE ALL ON FUNCTION public.read_pdc_jobcard_attachment_import_receipt(uuid) FROM public,anon,service_role;GRANT EXECUTE ON FUNCTION public.read_pdc_jobcard_attachment_import_receipt(uuid) TO authenticated;CREATE TABLE public.pdc_uid635_readback_contract_repairs_488(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid635-null-hours-canonical-readback'),failed_uid bigint NOT NULL CHECK(failed_uid=635),failed_stock text NOT NULL CHECK(failed_stock='13000775'),failure_code text NOT NULL CHECK(failure_code='canonical_receipt_drift'),repair_scope text NOT NULL CHECK(repair_scope='compare operation hours and estimated-hours provenance to the canonical source-row receipt with NULL-safe equality'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_readback_contract_repairs_488 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_readback_contract_repairs_488 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_readback_contract_repairs_488(action_key,failed_uid,failed_stock,failure_code,repair_scope) VALUES('uid635-null-hours-canonical-readback',635,'13000775','canonical_receipt_drift','compare operation hours and estimated-hours provenance to the canonical source-row receipt with NULL-safe equality');DO $p$ BEGIN IF pg_get_functiondef('public.read_pdc_jobcard_attachment_import_receipt(uuid)'::regprocedure) NOT LIKE '%ol.estimated_hours_source is distinct from sr.estimated_hours_source%' OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards) THEN RAISE EXCEPTION 'PDC_488_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827038000','488_null_hours_canonical_readback',ARRAY['Repair the exact canonical_receipt_drift exposed by the controlled UID635 rollback rehearsal','Use NULL-safe equality for hours and compare each operation provenance to its immutable source-row receipt','Keep unknown hours NULL and preserve owner_supplied_document_unknown','Keep UID635 Inbox-retained and writer contained pending exact retry','Production untouched']);COMMIT;
